# -*- coding: utf-8 -*-
from pathlib import Path
import sys, base64
ROOT = Path(__file__).resolve().parent
if not (ROOT / "app" / "components" / "PWASetup.js").exists():
    print("ERROR: corre esto DENTRO de musica-libre")
    print("Estas en:", ROOT)
    sys.exit(1)
D0 = """\\

"""
p = ROOT / "app/components/PWASetup.js"
p.write_bytes(base64.b64decode(D0))
t = p.read_text(encoding="utf-8")
ok = "export default function PWASetup" in t and "instalacionPospuesta" not in t and t.count("function infoNavegador")==1
print("ESCRITO app/components/PWASetup.js", p.stat().st_size)
print("LISTO" if ok else "FALLO")
if not ok: sys.exit(1)
print("IMPORTANTE: GitHub Desktop debe mostrar app/components/PWASetup.js")
print("mensaje: Aviso de inicio cada vez en Safari")
